import { expect, test, uniqueName } from "../../fixtures";

test.describe("vendor names are unique within a tenant", () => {
  test("creating a vendor whose name differs only by case is rejected with vendor_name_taken", { tag: "@VEN-03" }, async ({ apiAs }) => {
    // Arrange: an existing vendor in the member's tenant
    const member = await apiAs("member");
    const base = uniqueName("Acme Freight");
    const existing = await member.post("/api/vendors", {
      data: { name: base, category: "logistics", contact_email: "ops@acmefreight.example" },
    });
    expect(existing.status(), await existing.text()).toBe(201);

    // Act: create a vendor whose name matches the existing one ignoring case
    const duplicate = await member.post("/api/vendors", {
      data: { name: base.toLowerCase(), category: "logistics", contact_email: "ops@acmefreight.example" },
    });

    // Assert
    const body = await duplicate.text();
    expect(duplicate.status(), body).toBe(409);
    expect(JSON.parse(body).error.code, body).toBe("vendor_name_taken");
  });
});
